import { createHmac } from 'node:crypto';
export function createSecureTransport({ key, sink }) {
  let prev = Buffer.alloc(0);
  let seq = 0n;
  return (line) => {                                  // pino transport: one record per call
    const body = canonicalise(line);                  // stable key order, secrets already redacted
    prev = createHmac('sha256', key)
      .update(prev).update(seq.toString()).update(body)
      .digest();
    sink.append({ seq: seq++, tag: prev.toString('base64'), body });  // O_APPEND, fsync policy
  };
}
